-- Identity and policy entities (plan 36bakiw8 sections 4 and 6; decisions
-- uamxx6ba, 490o45d0, v6piaxdb).
--
-- Conventions used by every migration:
--   * uuid primary keys generated by the database, timestamptz everywhere;
--   * user-scoped tables carry user_id, are ENABLED and FORCED into row-level
--     security, and have one policy comparing user_id with app_user_id();
--   * global tables have no policy; gateway_app gets the DML it needs;
--   * gateway_jobs (BYPASSRLS) gets full DML on everything.
-- Creating a user happens before a user scope exists (just-in-time on first
-- company sign-in), so it goes through the bypass role; the users policy only
-- lets a scoped transaction see and update its own row.

-- +goose Up
CREATE TABLE users (
    id                       uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    display_name             text        NOT NULL DEFAULT '',
    status                   text        NOT NULL DEFAULT 'active'
                                         CHECK (status IN ('active', 'disabled')),
    last_company_sign_in_at  timestamptz,
    disabled_at              timestamptz,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE users FORCE ROW LEVEL SECURITY;
CREATE POLICY users_self ON users
    USING (id = app_user_id()) WITH CHECK (id = app_user_id());
GRANT SELECT, INSERT, UPDATE, DELETE ON users TO gateway_app, gateway_jobs;

-- Identity = provider issuer + permanent subject, never email.
CREATE TABLE identities (
    id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         uuid        NOT NULL REFERENCES users(id),
    issuer          text        NOT NULL,
    subject         text        NOT NULL,
    last_sign_in_at timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (issuer, subject)
);
CREATE INDEX identities_user_id_idx ON identities (user_id);
ALTER TABLE identities ENABLE ROW LEVEL SECURITY;
ALTER TABLE identities FORCE ROW LEVEL SECURITY;
CREATE POLICY identities_user_scope ON identities
    USING (user_id = app_user_id()) WITH CHECK (user_id = app_user_id());
GRANT SELECT, INSERT, UPDATE, DELETE ON identities TO gateway_app, gateway_jobs;

-- Portal / OAuth browser sessions. Only a hash of the session secret is stored.
CREATE TABLE sessions (
    id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid        NOT NULL REFERENCES users(id),
    token_hash   bytea       NOT NULL UNIQUE,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    last_seen_at timestamptz,
    revoked_at   timestamptz
);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions FORCE ROW LEVEL SECURITY;
CREATE POLICY sessions_user_scope ON sessions
    USING (user_id = app_user_id()) WITH CHECK (user_id = app_user_id());
GRANT SELECT, INSERT, UPDATE, DELETE ON sessions TO gateway_app, gateway_jobs;

-- Roles are structured data (per app/tool outcome, argument rules, personal
-- account allowance) edited by admins; global.
CREATE TABLE roles (
    id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text        NOT NULL UNIQUE,
    description text        NOT NULL DEFAULT '',
    definition  jsonb       NOT NULL DEFAULT '{}'::jsonb,
    is_default  boolean     NOT NULL DEFAULT false,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX roles_single_default_idx ON roles (is_default) WHERE is_default;
GRANT SELECT, INSERT, UPDATE, DELETE ON roles TO gateway_app, gateway_jobs;

CREATE TABLE role_assignments (
    user_id     uuid        NOT NULL REFERENCES users(id),
    role_id     uuid        NOT NULL REFERENCES roles(id),
    assigned_by uuid        REFERENCES users(id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_id)
);
ALTER TABLE role_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE role_assignments FORCE ROW LEVEL SECURITY;
CREATE POLICY role_assignments_user_scope ON role_assignments
    USING (user_id = app_user_id()) WITH CHECK (user_id = app_user_id());
GRANT SELECT, INSERT, UPDATE, DELETE ON role_assignments TO gateway_app, gateway_jobs;

-- Compiled Cedar policy sets, one row per change, identified by a hash so
-- approvals, ledger and audit rows can record exactly which version applied.
CREATE TABLE policy_versions (
    id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    version_hash text        NOT NULL UNIQUE,
    cedar        text        NOT NULL,
    source       jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at   timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT ON policy_versions TO gateway_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON policy_versions TO gateway_jobs;

-- Per-user narrowing on top of the role (structured, like roles).
CREATE TABLE user_restrictions (
    id         uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    uuid        NOT NULL REFERENCES users(id),
    definition jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_by uuid        REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX user_restrictions_user_id_idx ON user_restrictions (user_id);
ALTER TABLE user_restrictions ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_restrictions FORCE ROW LEVEL SECURITY;
CREATE POLICY user_restrictions_user_scope ON user_restrictions
    USING (user_id = app_user_id()) WITH CHECK (user_id = app_user_id());
GRANT SELECT, INSERT, UPDATE, DELETE ON user_restrictions TO gateway_app, gateway_jobs;

-- +goose Down
DROP TABLE IF EXISTS user_restrictions;
DROP TABLE IF EXISTS policy_versions;
DROP TABLE IF EXISTS role_assignments;
DROP TABLE IF EXISTS roles;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS identities;
DROP TABLE IF EXISTS users;
